          function streamAnswerHtml(target, html, onComplete) {
            var source = document.createElement("div");
            var jobs = [];
            source.innerHTML = html;
            target.innerHTML = "";
            function cloneForStreaming(node, parent) {
              if (node.nodeType === Node.TEXT_NODE) {
                var output = document.createTextNode("");
                parent.appendChild(output);
                jobs.push({ node: output, text: node.nodeValue || "", index: 0 });
                return;
              }
              if (node.nodeType !== Node.ELEMENT_NODE) return;
              var clone = node.cloneNode(false);
              parent.appendChild(clone);
              Array.prototype.forEach.call(node.childNodes, function (child) { cloneForStreaming(child, clone); });
            }
            Array.prototype.forEach.call(source.childNodes, function (node) { cloneForStreaming(node, target); });
            target.classList.add("is-typing");
            var jobIndex = 0;
            function typeNext() {
              var budget = 3;
              while (budget > 0 && jobIndex < jobs.length) {
                var job = jobs[jobIndex];
                if (job.index >= job.text.length) { jobIndex += 1; continue; }
                job.node.nodeValue += job.text.charAt(job.index);
                job.index += 1;
                budget -= 1;
              }
              scrollChatToBottom();
              if (jobIndex < jobs.length) window.setTimeout(typeNext, 18);
              else {
                target.classList.remove("is-typing");
                if (onComplete) onComplete();
              }
            }
            typeNext();
          }

          function renderAssistantResponse(host, answer, resultMarkup, onDone, skillName, instant) {
            var skill = skillName || "附近门店查询服务";
            host.innerHTML = '<button class="lx-store-skill-summary is-collapsed" type="button" aria-expanded="false"><span data-skill-summary>正在分析用户意图</span><span class="lx-store-skill-caret" aria-hidden="true"></span></button>' +
              '<div class="lx-store-skill-region"><img data-poc-icon="global-check.svg" alt=""><span data-skill-detail>Skill（' + skill + '）调用中</span></div>' +
              '<div class="lx-store-stream-copy"><p class="lx-store-answer-loading">正在为你查询门店信息…</p></div><div class="lx-store-result-stage">' + resultMarkup + '</div>';
            hydrateIcons(host);
            var summary = host.querySelector(".lx-store-skill-summary");
            var region = host.querySelector(".lx-store-skill-region");
            var copy = host.querySelector(".lx-store-stream-copy");
            var stage = host.querySelector(".lx-store-result-stage");
            function setCollapsed(collapsed) {
              summary.classList.toggle("is-collapsed", collapsed);
              summary.setAttribute("aria-expanded", String(!collapsed));
              region.classList.toggle("is-visible", !collapsed);
              scrollChatToBottom();
            }
            summary.addEventListener("click", function () { setCollapsed(!summary.classList.contains("is-collapsed")); });
            if (instant) {
              summary.classList.add("is-complete");
              host.querySelector("[data-skill-summary]").textContent = "已完成1个Skill工具调用";
              host.querySelector("[data-skill-detail]").textContent = "Skill（" + skill + "）已调用";
              copy.innerHTML = answer;
              stage.classList.add("is-visible");
              setCollapsed(false);
              if (onDone) onDone();
              return;
            }
            window.setTimeout(function () {
              host.querySelector("[data-skill-summary]").textContent = "正在获取数据";
              setCollapsed(false);
            }, 320);
            window.setTimeout(function () {
              summary.classList.add("is-complete");
              host.querySelector("[data-skill-summary]").textContent = "已完成1个Skill工具调用";
              host.querySelector("[data-skill-detail]").textContent = "Skill（" + skill + "）已调用";
              setCollapsed(false);
              var answerStartedAt = Date.now();
              function streamWhenReady() {
                var resolvedAnswer = typeof answer === "function" ? answer() : answer;
                if (!resolvedAnswer && Date.now() - answerStartedAt < 9000) { window.setTimeout(streamWhenReady, 120); return; }
                streamAnswerHtml(copy, resolvedAnswer || '<p>右侧导航路线已展开，请按地图提示前往目的门店。</p>', function () {
                stage.classList.add("is-visible");
                scrollChatToBottom();
                window.setTimeout(function () { if (onDone) onDone(); }, 180);
                });
              }
              streamWhenReady();
            }, 980);
          }

