          function requestPhoneVerificationCode() {
            var phoneInput = appointmentMask.querySelector("[data-phone-bind-number]");
            var button = appointmentMask.querySelector("[data-phone-code]");
            var phone = String(phoneInput?.value || "").replace(/\s/g, "");
            if (!/^1\d{10}$/.test(phone)) {
              setPhoneBindingMessage("请输入正确的 11 位手机号");
              phoneInput?.focus();
              return;
            }
            stopPhoneCodeTimer();
            phoneCodeRemaining = 60;
            button.disabled = true;
            button.textContent = phoneCodeRemaining + "s 后重试";
            setPhoneBindingMessage("验证码已发送，请输入短信验证码", true);
            phoneCodeTimer = window.setInterval(function () {
              phoneCodeRemaining -= 1;
              if (phoneCodeRemaining <= 0) {
                stopPhoneCodeTimer();
                button.disabled = false;
                button.textContent = "获取验证码";
                return;
              }
              button.textContent = phoneCodeRemaining + "s 后重试";
            }, 1000);
          }

