          function findStoreInQuery(value) {
            var normalized = String(value || "").replace(/[\s()（）]/g, "");
            return stores.find(function (store) { return normalized.includes(store.name.replace(/[\s()（）]/g, "")); });
          }

          function chineseStoreNumber(value) {
            var digits = { "一": 1, "二": 2, "两": 2, "三": 3, "四": 4, "五": 5, "六": 6, "七": 7, "八": 8, "九": 9 };
            if (/^\d+$/.test(value)) return Number(value);
            if (value === "十") return 10;
            if (value.includes("十")) {
              var parts = value.split("十");
              return (parts[0] ? digits[parts[0]] : 1) * 10 + (parts[1] ? digits[parts[1]] : 0);
            }
            return digits[value] || 0;
          }

          function findStoreOrdinalInQuery(value) {
            var match = String(value || "").match(/第?([1-9]\d?|[一二两三四五六七八九十]+)(?:个|家)?门店/);
            if (!match) return null;
            var index = chineseStoreNumber(match[1]) - 1;
            var listedStores = Array.from(page.querySelectorAll("[data-store-list] [data-store-id]")).map(function (item) {
              var id = item.getAttribute("data-store-id");
              return stores.find(function (store) { return store.id === id; });
            }).filter(Boolean);
            var orderedStores = listedStores.length ? listedStores : visibleStores;
            return index >= 0 ? (orderedStores[index] || null) : null;
          }

          function currentBrowsingStore(value) {
            return findStoreInQuery(String(value || "")) || findStoreOrdinalInQuery(value) || activeStore || visibleStores[0] || stores[0];
          }
