          function openNavigation(store, waitingSince) {
            if ((!baiduMap || !map.classList.contains('is-baidu-ready') || !window.BMapGL || !BMapGL.DrivingRoute) && Date.now()-(waitingSince||Date.now())<25000) {
              var started=waitingSince||Date.now();window.setTimeout(function(){if(page.isConnected)openNavigation(store,started);},150);return;
            }
            var silentNavigation = !!(options && options.navigationStore && options.navigationSilent);
            showSingleStoreScenario(store);
            page.querySelector("[data-route-back]").hidden = !!(options && options.navigationStore);
            if (!silentNavigation) window.parent.postMessage({ type: "lx-store-navigation-query", store: store }, window.location.origin);
            window.clearInterval(detailCarouselTimer);
            detailPage.classList.remove("is-active");
            appointmentMask.hidden = true;
            couponMask.hidden = true;
            activeStore = store;
            selectStore(store.id);
            var routeResult = null;
            var navigationBridgeSent = false;
            function routeAnswerHtml() {
              if (!routeResult) return "";
              if (routeResult.ok) return '<p>百度地图已在右侧规划从当前位置前往 <b>' + store.name + '</b> 的驾车路线：预计 <b>' + routeResult.duration + '</b> 到达（约 <b>' + routeResult.arrival + '</b>），全程 <b>' + routeResult.distance + '</b>。耗时会随实时路况变化，请以出发时的导航结果为准。</p>';
              return '<p>已在右侧展开前往 <b>' + store.name + '</b> 的导航地图。当前暂未获取到完整驾车耗时，请按地图路线提示前往；如需重新选择门店，可点击地图左上角“返回列表”。</p>';
            }
            function publishNavigationResult() {
              if (!routeResult || navigationBridgeSent) return;
              navigationBridgeSent = true;
              var baiduNavigationUrl = buildBaiduNavigationUrl(store);
              var navigationCard = navigationTurn && navigationTurn.querySelector('[data-card-action="baidu-navigation"]');
              if (navigationCard) navigationCard.dataset.baiduNavigationUrl = baiduNavigationUrl;
              if (!silentNavigation) window.parent.postMessage({ type: "lx-store-navigation-result", store: store, result: Object.assign({}, routeResult), url: baiduNavigationUrl }, window.location.origin);
            }
            var navigationTurn = silentNavigation ? null : appendAssistantTurn("驾车导航去" + store.name, routeAnswerHtml, (options && options.navigationStore || String(window.__lxState && window.__lxState.activeTabId || "").startsWith("info:store-navigation:")) ? null : "查看百度地图导航路线", null, "baidu-navigation", "门店导航服务");
            var routeTimeout = window.setTimeout(function () {
              if (!routeResult) { routeResult = { ok: false }; publishNavigationResult(); }
            }, 8000);
            if (baiduMap && map.classList.contains("is-baidu-ready") && window.BMapGL && BMapGL.DrivingRoute) {
              if (baiduDrivingRoute) baiduDrivingRoute.clearResults();
              baiduDrivingRoute = new BMapGL.DrivingRoute(baiduMap, {
                renderOptions: { map: baiduMap, autoViewport: true },
                onSearchComplete: function (results) {
                  window.clearTimeout(routeTimeout);
                  if (baiduDrivingRoute.getStatus() !== BMAP_STATUS_SUCCESS || !results || !results.getPlan || !results.getPlan(0)) {
                    routeResult = { ok: false };
                    publishNavigationResult();
                    return;
                  }
                  var plan = results.getPlan(0);
                  var durationSeconds = Number(plan.getDuration(false)) || 0;
                  var arrivalTime = new Date(Date.now() + durationSeconds * 1000);
                  routeResult = {
                    ok: true,
                    duration: plan.getDuration(true),
                    distance: plan.getDistance(true),
                    arrival: arrivalTime.toLocaleTimeString("zh-CN", { hour: "2-digit", minute: "2-digit", hour12: false })
                  };
                  publishNavigationResult();
                }
              });
              baiduDrivingRoute.search(new BMapGL.Point(userCoordinate.lng, userCoordinate.lat), new BMapGL.Point(store.lng, store.lat));
            } else {
              window.clearTimeout(routeTimeout);
              routeResult = { ok: false };
              publishNavigationResult();
            }
          }
          var detailCarouselTimer = null;
